import { describe, expect, it } from 'vitest';
import { redactMcpArgv, redactMcpText } from '../../src/codex/mcp/redaction.js';

describe('codex mcp redaction', () => {
  it('redacts env values in argv', () => {
    expect(redactMcpArgv([
      'mcp',
      'add',
      'github',
      '--env',
      'GITHUB_TOKEN=secret',
      '--env',
      'SAFE=value',
      '--',
      'node',
      'server.js'
    ])).toEqual([
      'mcp',
      'add',
      'github',
      '--env',
      'GITHUB_TOKEN=[REDACTED]',
      '--env',
      'SAFE=[REDACTED]',
      '--',
      'node',
      'server.js'
    ]);
  });

  it('redacts separated token-like argv values', () => {
    expect(redactMcpArgv([
      'mcp',
      'add',
      'github',
      '--',
      'node',
      'server.js',
      '--api-key',
      'secret-value',
      '--safe',
      'visible'
    ])).toEqual([
      'mcp',
      'add',
      'github',
      '--',
      'node',
      'server.js',
      '[REDACTED]',
      '[REDACTED]',
      '--safe',
      'visible'
    ]);
  });

  it('redacts token-like text and url query secrets', () => {
    expect(redactMcpText('GITHUB_TOKEN=secret\nAuthorization: Bearer abc123')).toContain('GITHUB_TOKEN=[REDACTED]');
    expect(redactMcpText('Authorization: Bearer abc123')).toContain('Authorization: Bearer [REDACTED]');
    expect(redactMcpText('https://example.test/mcp?token=secret&safe=ok')).toContain('token=[REDACTED]');
  });

  it('redacts authorization credentials for common schemes and no scheme', () => {
    expect(redactMcpText('Authorization: Basic abc123')).toBe('Authorization: Basic [REDACTED]');
    expect(redactMcpText('Authorization: token abc123')).toBe('Authorization: token [REDACTED]');
    expect(redactMcpText('Authorization: abc123')).toBe('Authorization: [REDACTED]');
  });

  it('redacts exact sensitive values', () => {
    expect(redactMcpText('server responded with exact-secret', ['exact-secret'])).toBe(
      'server responded with [REDACTED]'
    );
  });
});

import type { CodexProviderConfig, CodexRuntimeReadiness, GatewayAccountState } from '@opencreator/protocol';
import { cleanup, render, screen, waitFor } from '@testing-library/react';
import { userEvent } from '@testing-library/user-event';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { LanguageProvider } from '../../i18n/LanguageProvider.js';
import type { GatewayAccountSettingsService } from '../../services/gateway-account-service.js';
import {
  StartupAgentSetup, type AgentSetupService
} from './StartupAgentSetup.js';
import { availableAgentMode, confirmAgentSetup, isAgentSetupConfirmed, type AgentSetupSnapshot } from './agent-setup-state.js';

function readiness(accountStatus: 'signed_out' | 'signed_in' | 'expired', state: 'ready' | 'degraded' | 'blocked' = 'ready'): CodexRuntimeReadiness {
  return {
    state,
    mode: 'bundled', version: 'test', commit: null, binaryPath: '/codex',
    codexHome: '/tmp/codex', checkedAt: new Date(0).toISOString(),
    account: { status: accountStatus === 'signed_in' ? 'ready' : 'not_authenticated', accountStatus },
    binary: { status: 'ready' }, protocol: { status: 'ready' }, models: { status: 'ready' },
    skills: { status: 'ready' }, toolServer: { status: 'ready' }, diagnostics: []
  };
}

function createService(): AgentSetupService {
  let provider: CodexProviderConfig = { baseUrl: '', model: '', apiKeyConfigured: false, authentication: 'none' };
  let accountStatus: 'signed_in' | 'signed_out' = 'signed_out';
  return {
    getCodexReadiness: vi.fn(async () => readiness(accountStatus)),
    getCodexProvider: vi.fn(async () => provider),
    updateCodexProvider: vi.fn(async input => {
      accountStatus = 'signed_in';
      provider = { baseUrl: input.baseUrl, model: input.model, apiKeyConfigured: true, authentication: 'api_key' };
      return provider;
    })
  };
}

function mount(service: AgentSetupService, initialSnapshot?: AgentSetupSnapshot) {
  const onReady = vi.fn();
  const onSkip = vi.fn();
  render(<LanguageProvider initialPreference="zh-CN">
    <StartupAgentSetup service={service} initialSnapshot={initialSnapshot} onReady={onReady} onSkip={onSkip} />
  </LanguageProvider>);
  return { onReady, onSkip };
}

describe('StartupAgentSetup', () => {
  afterEach(() => { cleanup(); window.localStorage.clear(); });

  it('only offers reuse for a ready Codex with usable credentials', () => {
    const provider: CodexProviderConfig = { baseUrl: 'https://gateway.example.test/v1', model: 'model-1', apiKeyConfigured: true, authentication: 'api_key' };
    expect(availableAgentMode({ readiness: readiness('signed_out', 'degraded'), provider })).toBe('api_key');
    expect(availableAgentMode({ readiness: readiness('signed_out', 'degraded'), provider: { ...provider, model: '' } })).toBeNull();
    expect(availableAgentMode({ readiness: readiness('signed_out', 'degraded'), provider: { ...provider, apiKeyConfigured: false } })).toBeNull();
    expect(availableAgentMode({ readiness: readiness('signed_out', 'degraded'), provider: { ...provider, baseUrl: '' } })).toBeNull();
    expect(availableAgentMode({ readiness: readiness('signed_out', 'blocked'), provider })).toBeNull();
    expect(availableAgentMode({ readiness: readiness('expired', 'degraded'), provider: {
      ...provider, baseUrl: '', apiKeyConfigured: false, authentication: 'chatgpt'
    } })).toBeNull();
  });

  it('confirms an existing ChatGPT sign-in without a second detection or a key form', async () => {
    const service = createService();
    const provider: CodexProviderConfig = { baseUrl: '', model: 'gpt-test', apiKeyConfigured: false, authentication: 'chatgpt' };
    const snapshot = { readiness: readiness('signed_in'), provider };
    const { onReady } = mount(service, snapshot);
    expect(isAgentSetupConfirmed(snapshot)).toBe(false);
    await userEvent.setup().click(screen.getByRole('button', { name: '本地模式' }));
    expect(screen.getByText('已找到本机 Codex')).toBeInTheDocument();
    expect(screen.getByText(/ChatGPT 登录 · gpt-test/)).toBeInTheDocument();
    expect(screen.queryByLabelText('API Key')).not.toBeInTheDocument();
    await userEvent.setup().click(screen.getByRole('button', { name: '使用本机 Codex，继续' }));
    expect(onReady).toHaveBeenCalledWith(snapshot);
    expect(service.getCodexReadiness).not.toHaveBeenCalled();
    expect(service.getCodexProvider).not.toHaveBeenCalled();
    expect(service.updateCodexProvider).not.toHaveBeenCalled();
  });

  it('lets users choose a different provider even when local Codex is available', async () => {
    const service = createService();
    const snapshot: AgentSetupSnapshot = { readiness: readiness('signed_in'), provider: {
      baseUrl: '', model: 'gpt-test', apiKeyConfigured: false, authentication: 'chatgpt'
    } };
    const { onReady } = mount(service, snapshot);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    await user.click(screen.getByRole('button', { name: '自定义模型服务' }));
    expect(screen.getByRole('combobox', { name: '供应商' })).toBeInTheDocument();
    await user.selectOptions(screen.getByRole('combobox', { name: '供应商' }), 'deepseek');
    expect(screen.getByLabelText('Base URL')).toHaveValue('https://api.deepseek.com');
    expect(screen.getByLabelText('模型名称')).toHaveValue('deepseek-v4-pro');
    await user.type(screen.getByLabelText('API Key'), 'custom-key');
    await user.click(screen.getByRole('button', { name: '保存并开始使用' }));
    expect(service.updateCodexProvider).toHaveBeenCalledWith({
      baseUrl: 'https://api.deepseek.com', model: 'deepseek-v4-pro', apiKey: 'custom-key'
    });
    await waitFor(() => expect(onReady).toHaveBeenCalledOnce());
  });

  it('reuses a custom provider token without ChatGPT login or a second request', async () => {
    const service = createService();
    const provider: CodexProviderConfig = { baseUrl: 'https://gateway.example.test/v1', model: 'model-1', apiKeyConfigured: true, authentication: 'api_key' };
    const snapshot = { readiness: readiness('signed_out', 'degraded'), provider };
    const { onReady } = mount(service, snapshot);
    await userEvent.setup().click(screen.getByRole('button', { name: '本地模式' }));
    expect(screen.getByText(/API Key 已配置 · model-1/)).toBeInTheDocument();
    expect(screen.queryByLabelText('API Key')).not.toBeInTheDocument();
    await userEvent.setup().click(screen.getByRole('button', { name: '使用本机 Codex，继续' }));
    expect(onReady).toHaveBeenCalledWith(snapshot);
    expect(service.getCodexReadiness).not.toHaveBeenCalled();
    expect(service.getCodexProvider).not.toHaveBeenCalled();
    expect(service.updateCodexProvider).not.toHaveBeenCalled();
    confirmAgentSetup(snapshot);
    expect(isAgentSetupConfirmed(snapshot)).toBe(true);
    expect(isAgentSetupConfirmed({ ...snapshot, provider: { ...provider, apiKeyConfigured: false } })).toBe(false);
  });

  it('shows provider configuration only after choosing local mode', async () => {
    const service = createService();
    const { onReady } = mount(service);
    const user = userEvent.setup();
    expect(screen.queryByLabelText('API Key')).not.toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    const providerSelect = await screen.findByRole('combobox', { name: '供应商' });
    expect(providerSelect).toHaveValue('openai');
    expect(screen.getByLabelText('Base URL')).toHaveValue('https://api.openai.com/v1');
    expect(screen.getByLabelText('模型名称')).toHaveValue('gpt-5.6-sol');
    await user.selectOptions(providerSelect, 'minimax');
    expect(screen.queryByRole('button', { name: '使用 ChatGPT 登录' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: '使用本机 Codex，继续' })).not.toBeInTheDocument();
    expect(screen.getByLabelText('Base URL')).toHaveValue('https://api.minimax.io');
    expect(screen.getByLabelText('模型名称')).toHaveValue('MiniMax-M2.7');
    await user.type(screen.getByLabelText('API Key'), 'secret');
    await user.click(screen.getByRole('button', { name: '保存并开始使用' }));
    await waitFor(() => expect(onReady).toHaveBeenCalledOnce());
    expect(service.updateCodexProvider).toHaveBeenCalledWith({ baseUrl: 'https://api.minimax.io', model: 'MiniMax-M2.7', apiKey: 'secret' });
    expect(screen.getByLabelText('API Key')).toHaveValue('');
  });

  it('only reuses a saved key without editing the existing provider', async () => {
    const service = createService();
    const provider: CodexProviderConfig = { baseUrl: 'https://gateway.example.test/v1', model: 'model-1', apiKeyConfigured: true, authentication: 'api_key' };
    const snapshot = { readiness: readiness('signed_out', 'degraded'), provider };
    const { onReady } = mount(service, snapshot);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    await user.click(screen.getByRole('button', { name: '自定义模型服务' }));
    await user.clear(screen.getByLabelText('模型名称'));
    await user.type(screen.getByLabelText('模型名称'), 'new-model');
    expect(screen.getByRole('button', { name: '保存并开始使用' })).toBeDisabled();
    await user.clear(screen.getByLabelText('模型名称'));
    await user.type(screen.getByLabelText('模型名称'), 'model-1');
    await user.click(screen.getByRole('button', { name: '保存并开始使用' }));
    expect(onReady).toHaveBeenCalledWith(snapshot);
    expect(service.updateCodexProvider).not.toHaveBeenCalled();
  });

  it('retains the key on a failed save', async () => {
    const service = createService();
    vi.mocked(service.getCodexReadiness).mockResolvedValue(readiness('signed_out', 'blocked'));
    const { onReady } = mount(service);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    await user.selectOptions(await screen.findByRole('combobox', { name: '供应商' }), 'openai');
    await user.type(screen.getByLabelText('API Key'), 'secret');
    await user.click(screen.getByRole('button', { name: '保存并开始使用' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('模型服务尚未就绪');
    expect(screen.getByLabelText('API Key')).toHaveValue('secret');
    expect(onReady).not.toHaveBeenCalled();
  });

  it('allows the default OpenAI endpoint without a Base URL', async () => {
    const service = createService();
    const { onReady } = mount(service);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    await screen.findByRole('combobox', { name: '供应商' });
    await user.clear(screen.getByLabelText('Base URL'));
    await user.type(screen.getByLabelText('API Key'), 'secret');
    await user.click(screen.getByRole('button', { name: '保存并开始使用' }));
    expect(service.updateCodexProvider).toHaveBeenCalledWith({ baseUrl: '', model: 'gpt-5.6-sol', apiKey: 'secret' });
    await waitFor(() => expect(onReady).toHaveBeenCalledOnce());
  });

  it('retries initial detection after a transient error', async () => {
    const service = createService();
    vi.mocked(service.getCodexProvider).mockRejectedValueOnce(new Error('暂时无法读取')).mockResolvedValue({
      baseUrl: 'https://gateway.example.test/v1', model: 'model-1', apiKeyConfigured: true, authentication: 'api_key'
    });
    const { onReady } = mount(service);
    await userEvent.setup().click(screen.getByRole('button', { name: '本地模式' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('暂时无法读取');
    await userEvent.setup().click(screen.getByRole('button', { name: '重新检测' }));
    expect(await screen.findByText('已找到本机 Codex')).toBeInTheDocument();
    await userEvent.setup().click(screen.getByRole('button', { name: '使用本机 Codex，继续' }));
    expect(onReady).toHaveBeenCalledOnce();
  });

  it('supports skipping without changing local Codex', async () => {
    const service = createService();
    const { onSkip } = mount(service);
    await userEvent.setup().click(screen.getByRole('button', { name: '稍后配置，进入本地模式' }));
    expect(onSkip).toHaveBeenCalledOnce();
    expect(service.updateCodexProvider).not.toHaveBeenCalled();
  });

  it('offers both modes and never exposes provider fields in sign-in mode', async () => {
    mount(createService());
    expect(screen.getByRole('heading', { name: 'OpenCreator' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: '本地模式' })).toBeInTheDocument();
    await userEvent.setup().click(screen.getByRole('button', { name: '登录模式' }));
    expect(screen.getByRole('button', { name: '登录 OpenCreator' })).toBeDisabled();
    expect(screen.queryByLabelText('Base URL')).not.toBeInTheDocument();
    expect(screen.queryByLabelText('API Key')).not.toBeInTheDocument();
  });

  it('cancels browser authorization before returning to the local mode selector', async () => {
    let state: GatewayAccountState = { source: 'manual', authState: 'signed_out', activationState: 'inactive', account: null, bindingVersion: null, models: [], activationError: null };
    const gateway: GatewayAccountSettingsService = {
      getState: vi.fn(async () => state),
      start: vi.fn(async () => { state = { ...state, authState: 'authorizing' }; return { attemptId: 'a', authorizationUrl: 'https://gateway.example/device', expiresAt: '2026-11-01T00:00:00Z' }; }),
      cancel: vi.fn(async () => { state = { ...state, authState: 'signed_out' }; return state; }),
      activate: vi.fn(), logout: vi.fn(), setSource: vi.fn(), selectModel: vi.fn(), getBalance: vi.fn(), getSummary: vi.fn(), getPlans: vi.fn(), getOrders: vi.fn(), getOrder: vi.fn(), getCreditGrants: vi.fn(), checkout: vi.fn(), portal: vi.fn()
    };
    render(<LanguageProvider initialPreference="zh-CN"><StartupAgentSetup service={createService()} gatewayService={gateway} onReady={vi.fn()} onSkip={vi.fn()}/></LanguageProvider>);
    const user = userEvent.setup();
    await user.click(screen.getByRole('button', { name: '登录模式' }));
    await waitFor(() => expect(screen.getByRole('button', { name: '登录 OpenCreator' })).toBeEnabled());
    await user.click(screen.getByRole('button', { name: '登录 OpenCreator' }));
    expect(await screen.findByText('请在浏览器中完成登录')).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: '返回' }));
    expect(gateway.cancel).toHaveBeenCalledOnce();
    await user.click(screen.getByRole('button', { name: '本地模式' }));
    expect(await screen.findByLabelText('API Key')).toBeInTheDocument();
  });
});

import { expect, it } from 'vitest';
import type { GatewayModel } from '@opencreator/protocol';
import { officialModelPrice, officialModelPriceDescription } from './official-model-pricing.js';

const zh = (value: string) => value;
const en = (_: string, value: string) => value;
const model = (modality: GatewayModel['modality'], price: NonNullable<GatewayModel['price']>, extra: Partial<GatewayModel> = {}): GatewayModel => ({ id: 'test', modality, capabilities: [], price, ...extra });
const video = model('video', { version: 'v1', videoUnitsPerSecond: { '480p': 10_000_000, '720p': 37_354_133, '1080p': 44_824_959 } }, { durations: [4, 6, 8], resolutions: ['480p', '720p', '1080p'], aspectRatios: ['9:16', '16:9'] });

it.each([
  [model('text', { version: 'v1', inputPerMillion: 2091.831996, outputPerMillion: 10459.15998 }), '输入 2092 / 输出 10459 积分/百万 token', 'Input 2092 / output 10459 credits/M tokens'],
  [model('text', { version: 'v1', inputPerMillion: 119.533223, outputPerMillion: 478.132891 }), '输入 120 / 输出 478 积分/百万 token', 'Input 120 / output 478 credits/M tokens'],
  [model('image', { version: 'v1', billing: 'usage', inputPerMillion: 5229.57999, imageInputPerMillion: 10459.15998, outputPerMillion: 31377.47994 }), '约 64 积分/张', 'About 64 credits / image'],
  [model('image', { version: 'legacy', perRequest: 10 }), '约 10 积分/张', 'About 10 credits / image'],
  [model('speech', { version: 'v1', perMillionCharacters: 15688.735488 }), '约 16 积分/千字符', 'About 16 credits / 1,000 characters'],
  [model('speech', { version: 'v1', perMillionCharacters: 31377.470976 }), '约 31 积分/千字符', 'About 31 credits / 1,000 characters'],
  [model('speech', { version: 'legacy', perMinute: 20, perMillionCharacters: 4000 }), '约 21 积分/分钟', 'About 21 credits / minute'],
  [model('transcription', { version: 'v1', perMinute: 6.275494 }), '约 6 积分/分钟', 'About 6 credits / minute'],
  [video, '约 37 积分/秒 · 720p', 'About 37 credits/second · 720p'],
] as const)('uses the requested billing unit for %j', (value, chinese, english) => {
  expect(officialModelPrice(value, zh)).toBe(chinese);
  expect(officialModelPrice(value, en)).toBe(english);
});

it('quotes each video second at a supported resolution independently of clip duration', () => {
  expect(officialModelPriceDescription(video, zh)).toContain('720p：约 37 积分/秒');
  const fallback = { ...video, durations: [4, 6], resolutions: ['1080p'], aspectRatios: ['9:16'] };
  expect(officialModelPrice(fallback, zh)).toBe('约 45 积分/秒 · 1080p');
  expect(officialModelPriceDescription(fallback, zh)).toContain('1080p：约 45 积分/秒');
  expect(officialModelPrice({ ...video, durations: [] }, zh)).toBe(officialModelPrice(video, zh));
});

it('retains the workload assumptions and actual tariffs in price descriptions', () => {
  const text = model('text', { version: 'v1', inputPerMillion: 2091.83, cachedInputPerMillion: 104.59, cacheWritePerMillion: 2614.79, outputPerMillion: 10459.16 });
  expect(officialModelPriceDescription(text, zh)).toContain('按上游实际输入、输出');
  expect(officialModelPriceDescription(text, zh)).toContain('缓存输入 105');
  expect(officialModelPriceDescription(text, zh)).toContain('缓存写入 2615');
  expect(officialModelPriceDescription(model('transcription', { version: 'v1', perMinute: 6.275494 }), zh)).toContain('不足一分钟按比例扣积分');
});

it('does not present audio-only estimates for token-priced speech', () => {
  const speech = model('speech', { version: 'v1', inputPerMillion: 14343.986732, perMinute: 17.929983 });
  expect(officialModelPrice(speech, zh)).toBe('暂无法估算');
  expect(officialModelPriceDescription(speech, zh)).toContain('文本输入 14344 积分/百万 token + 18 积分/分钟');
});

it('keeps integer rates and never substitutes a fixed text call or video clip price', () => {
  expect(officialModelPrice(model('text', { version: 'v1', inputPerMillion: 1499.9996, outputPerMillion: 0.0001 }), zh)).toBe('输入 1500 / 输出 <1 积分/百万 token');
  expect(officialModelPrice(model('text', { version: 'v1', inputPerMillion: 150, outputPerMillion: 600 }), zh)).toBe('输入 150 / 输出 600 积分/百万 token');
  expect(officialModelPrice(video, zh)).not.toContain('积分/段');
});

it('does not guess missing or invalid model prices', () => {
  expect(officialModelPrice({ ...video, price: undefined }, zh)).toBe('');
  for (const value of [model('image', { version: 'v1', billing: 'usage', outputPerMillion: 100 }), model('speech', { version: 'v1', perMillionCharacters: NaN })]) {
    expect(officialModelPrice(value, zh)).toBe('暂无法估算');
  }
  expect(officialModelPrice({ ...video, resolutions: [] }, zh)).toBe('价格暂不可用');
});

import { fireEvent, render, screen, within } from '@testing-library/react';
import { userEvent } from '@testing-library/user-event';
import { expect, it, vi } from 'vitest';
import OfficialModelSelect from './OfficialModelSelect.js';
import { gatewayRecommendedModelId, type GatewayModel } from '@opencreator/protocol';
import { LanguageProvider } from '../../i18n/LanguageProvider.js';

function catalog() {
  const models = Array.from({ length: 12 }, (_, index) => ({ id: `vendor/model-${index}`, name: `Model ${index}`, modality: 'text' as const, capabilities: ['responses'] }));
  models.push({ id: 'openrouter/auto', name: 'OpenRouter Automatic', modality: 'text', capabilities: ['responses'] });
  return models;
}

it('shows locally hosted brand marks and only model-supported video details', async () => {
  const models = [
    { id: 'bytedance/seedance-2', name: 'Seedance 2.0', modality: 'video' as const, capabilities: [], durations: [5, 10] },
    { id: 'google/veo-3.1', name: 'Veo 3.1', modality: 'video' as const, capabilities: [], durations: [4, 8], resolutions: ['720p'] },
    { id: 'custom/private-video', name: 'Private Video', modality: 'video' as const, capabilities: [] }
  ];
  render(<OfficialModelSelect label="视频模型" models={models} value={models[0]!.id} onChange={vi.fn()} />);
  const input = screen.getByRole('combobox');
  expect(input.parentElement?.querySelector('[data-brand="bytedance"] img')).toHaveAttribute('src', '/model-brands/bytedance-color.svg');
  await userEvent.setup().click(input);
  const veo = screen.getByRole('option', { name: 'Veo 3.1' });
  expect(veo.querySelector('[data-brand="google"] img')).toHaveAttribute('src', '/model-brands/google-color.svg');
  expect(veo).toHaveTextContent('Google · 4 / 8 秒 · 720p');
  const unknown = screen.getByRole('option', { name: 'Private Video' });
  expect(unknown.querySelector('[data-brand="generic"] svg')).not.toBeNull();
  expect(unknown).not.toHaveTextContent(/秒|720p/);
  expect(within(unknown).queryByRole('img')).not.toBeInTheDocument();
});

it('keeps options usable if a brand image fails to load', async () => {
  const change = vi.fn();
  render(<OfficialModelSelect label="模型" models={[{ id: 'kling-v2-1-master', name: 'Kling 2.1 Master', modality: 'video', capabilities: [] }]} value="" onChange={change} />);
  await userEvent.setup().click(screen.getByRole('combobox'));
  const option = screen.getByRole('option', { name: 'Kling 2.1 Master' });
  fireEvent.error(option.querySelector('img')!);
  expect(option.querySelector('img')).toBeNull();
  expect(option.querySelector('svg')).not.toBeNull();
